class FastScanner {

	private in: Deno.Reader;
	private buffer = new Uint8Array(1024);
	private length = 0;
	private p = 0;

	constructor (stream: Deno.Reader) {
		this.in = stream;
	}

	async hasNextByte () {
		if (this.p < this.length) return true;
		else {
			this.p = 0;
			try {this.length = await this.in.read(this.buffer);}
			catch (e) {e.printStackTrace();}
			if (this.length <= 0) return false;
		}
		return true;
	}

	async readByte () {
		if (await this.hasNextByte() == true) return this.buffer[this.p++];
		return -1;
	}

	isPrintable (n: number) {return 33<=n&&n<=126;}

	async skip () {
		while (await this.hasNextByte() && !this.isPrintable(this.buffer[this.p])) this.p++;
	}

	async hasNext () {await this.skip(); return await this.hasNextByte();}

	async next () {
		if (!await this.hasNext()) throw new Error();
		const sb = new ArrayBuffer(1024);
		const view = new Uint8Array(sb);
		let t = await this.readByte();
		while (this.isPrintable(t)) {
			view[view.length] = t;
			t = await this.readByte();
		}
		return new TextDecoder().decode(sb.slice(0, view.length));
	}

	async nextArray (n: number) {
		const ar = new Array(n);
		for (let i=0; i<n; i++) ar[i] = await this.next();
		return ar;
	}

	async nextInt () {return Number(await this.next());}

	async nextIntArray (n: number) {
		const ar = new Array(n);
		for (let i=0; i<n; i++) ar[i] = await this.nextInt();
		return ar;
	}

	async nextLong () {
		if (!await this.hasNext()) throw new Error();
		let minus = false;
		let temp = await this.readByte();
		if (temp == '-'.charCodeAt(0)) {
			minus = true;
			temp = await this.readByte();
		}
		if (temp<'0'.charCodeAt(0) || '9'.charCodeAt(0)<temp) throw new Error();
		let n = 0;
		while (this.isPrintable(temp)) {
			if ('0'.charCodeAt(0)<=temp && temp<='9'.charCodeAt(0)) {
				n *= 10;
				n += temp - '0'.charCodeAt(0);
			}
			else throw new Error();
			temp = await this.readByte();
		}
		return minus? -n : n;
	}

	async nextLongArray (n: number) {
		const ar = new Array(n);
		for (let i=0; i<n; i++) ar[i] = await this.nextLong();
		return ar;
	}

	async nextDouble () {
		return Number(await this.next());
	}

	async nextDoubleArray (n: number) {
		const ar = new Array(n);
		for (let i=0; i<n; i++) ar[i] = await this.nextDouble();
		return ar;
	}

	close () {
		try {this.in.close();}
		catch(e){}
	}

}

class PrintWriter {

	private out: Deno.Writer;
	private buffer = new Uint8Array(1024);
	private length = 0;

	constructor (stream: Deno.Writer) {
		this.out = stream;
	}

	write (n: number) {
		this.buffer[this.length++] = n;
	}

	writeString (s: string) {
		for (let i=0; i<s.length; i++) this.write(s.charCodeAt(i));
	}

	println (s: string) {
		this.writeString(s);
		this.write('\n'.charCodeAt(0));
		this.flush();
	}

	flush () {
		this.out.write(this.buffer.slice(0, this.length));
		this.length = 0;
	}

	close () {
		this.flush();
		try {this.out.close();}
		catch(e){}
	}

}

