import { Readable, Writable } from "stream";

export class FastScanner {

	private in: Readable;
	private buffer: Buffer;
	private length: number = 0;
	private p: number = 0;

	constructor (stream: Readable) {
		this.in = stream;
		this.buffer = Buffer.alloc(1024);
	}

	hasNextByte () {
		if (this.p < this.length) return true;
		else {
			this.p = 0;
			try {this.length = this.in.read(this.buffer);}
			catch (e) {e.printStackTrace();}
			if (this.length <= 0) return false;
		}
		return true;
	}

	readByte () {
		if (this.hasNextByte() == true) return this.buffer[this.p++];
		return -1;
	}

	isPrintable (n: number) {return 33<=n&&n<=126;}

	skip () {
		while (this.hasNextByte() && !this.isPrintable(this.buffer[this.p])) this.p++;
	}

	hasNext () {this.skip(); return this.hasNextByte();}

	next () {
		if (!this.hasNext()) throw new Error("NoSuchElementException");
		let sb = "";
		let t = this.readByte();
		while (this.isPrintable(t)) {
			sb += String.fromCharCode(t);
			t = this.readByte();
		}
		return sb;
	}

	nextArray (n: number) {
		let ar = new Array(n);
		for (let i=0; i<n; i++) ar[i] = this.next();
		return ar;
	}

	nextInt () {return this.nextLong();}

	nextIntArray (n: number) {
		let ar = new Array(n);
		for (let i=0; i<n; i++) ar[i] = this.nextInt();
		return ar;
	}

	nextLong () {
		if (!this.hasNext()) throw new Error("NoSuchElementException");
		let minus = false;
		let temp = this.readByte();
		if (temp == '-') {
			minus = true;
			temp = this.readByte();
		}
		if (temp<'0' || '9'<temp) throw new Error("NumberFormatException");
		let n = 0;
		while (this.isPrintable(temp)) {
			if ('0'<=temp && temp<='9') {
				n *= 10;
				n += temp - '0';
			}
			else throw new Error("NumberFormatException");
			temp = this.readByte();
		}
		return minus? -n : n;
	}

	nextLongArray (n: number) {
		let ar = new Array(n);
		for (let i=0; i<n; i++) ar[i] = this.nextLong();
		return ar;
	}

	nextDouble () {
		return parseFloat(this.next());
	}

	nextDoubleArray (n: number) {
		let ar = new Array(n);
		for (let i=0; i<n; i++) ar[i] = this.nextDouble();
		return ar;
	}

	close () {
		try {this.in.close();}
		catch(e){}
	}

}

