class PrintWriter {
  private out: OutputStream;
  private buffer: string[] = new Array(1024);
  private length: number = 0;

  constructor(stream: OutputStream) {
    this.out = stream;
  }

  print(...ar: any[]) {
    ar.forEach((a) => {
      if (typeof a == "string") {
        this.buffer.push(a);
      } else if (typeof a == "number") {
        this.buffer.push(String(a));
      } else if (typeof a == "boolean") {
        this.buffer.push(a ? "true" : "false");
      } else if (typeof a == "object") {
        this.buffer.push(JSON.stringify(a));
      }
    });
    this.length += ar.length;
    if (this.length >= this.buffer.length) {
      this.flush();
    }
  }

  println(...ar: any[]) {
    this.print(...ar);
    this.println();
  }

  println() {
    this.buffer.push("\n");
    this.length++;
    if (this.length >= this.buffer.length) {
      this.flush();
    }
  }

  flush() {
    try {
      this.out.write(this.buffer.join("").getBytes());
    } catch (e) {
      e.printStackTrace();
    }
    this.buffer = new Array(1024);
    this.length = 0;
  }

  close() {
    this.flush();
    try {
      this.out.close();
    } catch (e) {}
  }
}

