		let ar = new Array(n);
		for (let i=0; i<n; i++) ar[i] = this.next();
		return ar;
	}

	public nextInt () {
		return Math.toIntExact(this.nextLong());
	}

	public nextIntArray (n: number) {
		let ar = new Array(n);
		for (let i=0; i<n; i++) ar[i] = this.nextInt();
		return ar;
	}

	public nextLong () {
		if (!this.hasNext()) throw new NoSuchElementException();
		let minus = false;
		let temp = this.readByte();
		if (temp == '-') {
			minus = true;
			temp = this.readByte();
		}
		if (temp<'0' || '9'<temp) throw new NumberFormatException();
		let n = 0;
		while (this.isPrintable(temp)) {
			if ('0'<=temp && temp<='9') {
				n *= 10;
				n += temp - '0';
			}
			else throw new NumberFormatException();
			temp = this.readByte();
		}
		return minus? -n : n;
	}

	public nextLongArray (n: number) {
		let ar = new Array(n);
		for (let i=0; i<n; i++) ar[i] = this.nextLong();
		return ar;
	}

	public nextDouble () {
		return Number(this.next());
	}

	public nextDoubleArray (n: number) {
		let ar = new Array(n);
		for (let i=0; i<n; i++) ar[i] = this.nextDouble();
		return ar;
	}

	public close () {
		try {this.in.close();}
		catch(e){}
	}

}

export class PrintWriter {

	private out: OutputStream;

	constructor (stream: OutputStream) {
		this.out = stream;
	}

	public print (...ar: any[]) {
		ar.forEach(a => {
			if (a instanceof Array) {
				a.forEach(b => {
					this.out.write(b.toString());
				});
			}
			else {
				this.out.write(a.toString());
			}
		});
	}

	public println (...ar: any[]) {
		this.print(...ar);
		this.out.write("\n");
	}

	public close () {
		try {this.out.close();}
		catch(e){}
	}

}

